<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$cashier=(int)($_GET['cashier']??0);$sql="SELECT t.*,u.name cashier,p.method FROM transactions t JOIN users u ON u.id=t.cashier_id JOIN payments p ON p.transaction_id=t.id WHERE t.branch_id=? AND DATE(t.created_at) BETWEEN ? AND ?";$args=[branch_id(),$from,$to];if($cashier){$sql.=' AND t.cashier_id=?';$args[]=$cashier;}$sql.=' ORDER BY t.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$s=$pdo->prepare("SELECT id,name FROM users WHERE role='kasir' AND branch_id=? ORDER BY name");$s->execute([branch_id()]);$cashiers=$s->fetchAll();$pageTitle='Transaksi Cabang';$active='transaksi';include __DIR__.'/../includes/header.php';?>
<section class="card"><form class="filter-row"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><label>Kasir<select name="cashier"><option value="0">Semua kasir</option><?php foreach($cashiers as $c):?><option value="<?=$c['id']?>" <?=$cashier===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Tampilkan</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Tanggal</th><th>Kasir</th><th>Metode</th><th>Total</th><th>Laba</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['invoice'])?></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td><td><?=e($r['cashier'])?></td><td><?=ucfirst($r['method'])?></td><td><?=rupiah($r['total'])?></td><td><?=rupiah($r['profit'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">Belum ada transaksi.</div><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>
